import copy,hashlib,json
from pathlib import Path
root=Path(__file__).resolve().parents[2]; audit=root/'Examtopics/audit'
questions=json.loads((root/'Examtopics/output/complete_q1_q1396.json').read_text(encoding='utf-8')); by={q['id']:q for q in questions}
def fp(q):return hashlib.sha256(json.dumps(q,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def swap(n, changes):
 d=copy.deepcopy(by[n]['drag_drop_data']);d['sources']=[changes.get(s,s) for s in d['sources']]
 for t in d['targets']:t['expected']=changes.get(t['expected'],t['expected'])
 return d
fixes={
1211:dict(prompt='Classify each specified use by its indicated TCP or UDP transport. Treat the items as the stated common uses rather than exclusive protocol requirements; order within a group does not matter.',drag_drop_data=swap(1211,{'DNS':'a typical DNS query using UDP','HTTP':'HTTP/1.1 over TCP','RTP':'RTP over UDP','SNMP':'SNMP messages over UDP'}),answer_image=None,explanation='TCP 组：HTTP/1.1、SMTP、Telnet；UDP 组：题设 UDP DNS 查询、RTP 和 SNMP。DNS 同时支持 TCP，区域传送及其他查询可使用 TCP；HTTP/3 使用 QUIC/UDP，因此题设明确具体用法。原解答图将 SMTP 与 DNS 错置，已隐藏；原题图保留供核对。同组内顺序不限。'),
1212:dict(prompt='Classify these campus design characteristics under a typical collapsed-core or three-tier design. Within each category the order does not matter.',drag_drop_data=swap(1212,{'single device handles the core and the distribution layer':'the core and distribution functions are combined in the same layer','more cost-effective than other options':'often needs fewer devices than a comparable three-tier design','most appropriate for small network designs':'commonly used for smaller campus designs','enhances network availability':'uses a dedicated core layer to connect distribution blocks','separate devices handle the core and the distribution layer':'uses separate core and distribution layers'}),answer_image=None,explanation='折叠核心将核心与汇聚功能合并，常用于较小园区，可能减少设备；三层设计有独立核心层连接汇聚块。高可用与冗余取决于具体设计，折叠核心也可使用冗余设备，不能说三层必然更高可用或折叠核心只有一台交换机。已改写原图中含糊描述；同组内顺序不限。'),
1213:dict(prompt='Match TCP and UDP with the indicated transport-layer properties. Order within each group does not matter.',drag_drop_data=swap(1213,{'transmitted based on data contained in the packet without the need for a data channel':'sends datagrams without establishing a transport-layer connection','requires the client and the server to establish a connection before sending the packet':'establishes a connection before ordinary application data transfer','provides best-effort service':'does not itself guarantee delivery or retransmit lost datagrams'}),answer_image=None,explanation='TCP 面向连接，通过序号、确认与重传等机制提供可靠有序字节流；UDP 无连接，协议本身不保证交付或重传，应用仍可自行实现可靠性。原图“无需数据通道”含糊，现改为无需先建立传输层连接。每组内可交换。'),
1214:dict(prompt='Classify the adapted IPv6 examples by their address-prefix category. Order within each group does not matter.',drag_drop_data=swap(1214,{'fcba:926a:e8e:7a25:b1:c6d2:1a76:8fdc':'fdba:926a:e8e:7a25:b1:c6d2:1a76:8fdc'}),answer_image=None,explanation='2001:db8:600d:cafe::123 和 3ffe:e54d:620:a87a::f00d 在 2000::/3 全局单播格式范围内，但 2001:db8::/32 为文档前缀，3ffe::/16 为已退役 6bone 前缀，均不能据此认定实际可公网使用。fdba:... 和 fd6d:... 属 fd00::/8 本地分配 ULA；原图 fcba 的 L 位为 0，未定义为本地分配 ULA，故替换为 fdba。每组内可交换。'),
1215:dict(prompt='Classify the IPv6 examples by address format. Order within the global-unicast-format group does not matter.',explanation='2001:db8:600d:cafe::123 和 3ffe:e54d:620:a87a::f00d 落在 2000::/3 地址格式范围；前者是文档前缀，后者是已退役的 6bone 前缀，不能据此推断互联网可达。fe80::a00:27ff:feeb:89aa 是有效链路本地单播；ff05::1:3 为组播地址。两个全局单播格式槽位可互换。'),
1216:dict(prompt='Match each adapted description to the IPv6 delivery type. Each type has two descriptions and group members may be placed in either order.',drag_drop_data=swap(1216,{'used exclusively by a non-host device':'delivery is to one eligible interface selected by routing'}),answer_image=None,explanation='任播地址可分配给多个接口，但报文通常送到路由意义上最近的一个接口；不能说任播只能用于路由器，RFC 4291 已移除旧限制。组播使用 ff00::/8 并可一对多；单播标识单个接口，链路本地及回环属于单播。同组内任意顺序。原题及答案图中的 non-host 专用断言错误，已改写并隐藏错误答案图。'),
1217:dict(prompt='Match each adapted characteristic to global unicast or link-local IPv6 addresses. Each group has two slots and order within a group does not matter.',drag_drop_data=swap(1217,{'configured only once per interface':'packets using the address are not forwarded beyond the originating link','attached to a single subnet':'is scoped to the local link','routable and reachable via the Internet':'can be globally routed when allocated and permitted by routing and policy'}),answer_image=None,explanation='全局单播通常用于可全球路由的地址，类似公网 IPv4，但具体是否可达取决于分配、路由及策略。链路本地仅在链路内有效，路由器不应转发源或目的为链路本地的包。原答案图将公网可路由放入链路本地，且误称接口只可配置一个地址；已改写，修订后的两组各自可乱序。'),
1218:dict(prompt='Match the adapted IPv6 link-local and unique-local properties. Each group has two slots and group order does not matter.',drag_drop_data=swap(1218,{'configured only once per interface':'packets using the address are not forwarded beyond the originating link','attached to a single subnet':'used for communication scoped to one link','addressing for exclusive use internally without Internet routing':'intended for local communications and normally not routed on the public Internet'}),answer_image=None,explanation='链路本地地址作用域是单条链路，源或目的为链路本地的包不跨路由器转发。ULA 属 fc00::/7，当前本地分配形式为 fd00::/8，通常不在公网路由；原题“每接口只配置一次”不是通用限制，接口可有多个 IPv6 地址。组内可乱序。'),
1219:dict(prompt='Refer to the active Wi-Fi adapter in the exhibit. Assume its 192.168.1.20 address uses mask 255.255.255.0 and gateway 192.168.1.1. Match its identifiers with the requested network parameters.',explanation='活动 Wi-Fi 接口的 MAC 为 B8-76-3F-7C-57-DF，主机为 192.168.1.20、默认网关 192.168.1.1；/24 网络的广播为 192.168.1.255，最后可分配单播地址为 192.168.1.254。图中的 Wi-Fi Direct 虚拟适配器已断开，其 MAC 不用于此题。MAC 可能被本地配置或随机化，不能绝对保证全球唯一。'),
1220:dict(prompt='Match the DNS concepts and Cisco IOS client lookup command with the adapted descriptions.',drag_drop_data=(lambda d: ([(t.update({'label':'disables DNS hostname lookup by the Cisco device'}) if t['expected']=='no ip domain-lookup' else t.update({'label':'hierarchical name used for an administrative namespace in a URL hostname'}) if t['expected']=='domain' else None) for t in d['targets']],d)[1])(copy.deepcopy(by[1220]['drag_drop_data'])),answer_image=None,explanation='DNS 提供主机名与地址等记录查询；缓存存储先前结果以减少重复查询；resolver 根据请求进行名称查询；域名是层次化命名空间而非可靠地表明组织类型或地理位置。Cisco IOS `no ip domain-lookup` 关闭设备的 DNS 主机名查询，并不等同关闭所有 DNS 服务器或其他 DNS 服务。原图描述过宽，已改写对应标签。')}
